参考代码：

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    int t;
    cin >> t;
    while (t--) {
        int a, b;
        cin >> a >> b;
        long long s = 0;
        for (int i = a; i <= b; i++)
            if (i % 2 == 0) s += i;
        cout << s << endl;
    }
    return 0;
}
```

