#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, w;
    cin >> n >> w;
    int cnt = 0;
    int now = w;
    if (now >= 3600 && now <= 3700) cnt++;
    for (int i = 2; i <= n; i++) {
        int x;
        cin >> x;
        now += x;
        if (now >= 3600 && now <= 3700) cnt++;
    }
    cout << cnt << endl;
    return 0;
}
```

