#include <bits/stdc++.h>
using namespace std;
int a[105][105];
int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            cin >> a[i][j];
    for (int i = 0; i < n; i++) {
        int s = 0;
        for (int j = 0; j < m; j++)
            s += a[i][j];
        if (i > 0) cout << ' ';
        cout << s;
    }
    cout << endl;
    return 0;
}
```

